from collections import deque

@lru_cache(None)
def delay(b, p):
    if term(b):
        return 0
    q = "O" if p == "X" else "X"
    v = val(b, p)
    ds = [delay(ch, q) for _, ch in kids(b, p) if val(ch, q) == v]
    return 1 + (min(ds) if v == (1 if p == "X" else -1) else max(ds))

root = "." * 9
