```python
"""Standalone checker for certificate.json. Imports nothing from solver.py.

It re-implements the Shift-Tac rules from protocol.md and verifies that the
policy is a complete contingent winning strategy for X: at every X-to-move board
it reaches, the policy supplies a legal action; every legal O reply is either a
terminal X win or a board the policy also covers; no line ends in a draw, an O
win, or an uncovered board.

Exit status 0 = certificate verified, 1 = rejected.
"""

import json
import os
import sys
from collections import deque

LINES = [(0, 1, 2), (3, 4, 5), (6, 7, 8),
         (0, 3, 6), (1, 4, 7), (2, 5, 8),
         (0, 4, 8), (2, 4, 6)]


def outcome(board):
    """'X', 'O', 'D' if terminal (post-rotation board), else None."""
    won = set(board[a] for a, b, c in LINES
              if board[a] != '.' and board[a] == board[b] == board[c])
    if len(won) == 2:
        return 'D'
    if won:
        return won.pop()
    return 'D' if '.' not in board else None


def moves(board, player):
    """All (cell, axis, delta) -> resulting board, per the frozen convention."""
    out = []
    for cell in range(9):
        if board[cell] != '.':
            continue
        placed = list(board)
        placed[cell] = player
        r, c = divmod(cell, 3)
        for axis in ('R', 'C'):
            idx = (3 * r, 3 * r + 1, 3 * r + 2) if axis == 'R' else (c, c + 3, c + 6)
            for delta in (-1, 1):
                nb = list(placed)
                for p, i in enumerate(idx):
                    nb[idx[(p + delta) % 3]] = placed[i]
                out.append(((cell, axis, delta), ''.join(nb)))
    return out


def to_move(board):
    return 'X' if (9 - board.count('.')) % 2 == 0 else 'O'


def check(cert):
    policy = cert['policy']
    root = cert['root']
    errors = []
    if len(root) != 9 or any(ch not in '.XO' for ch in root):
        return ['malformed root board'], {}
    if cert.get('root_player', 'X') != 'X' or to_move(root) != 'X':
        errors.append('root is not an X-to-move board')

    seen = {root}
    queue = deque([root])
    x_nodes = 0
    o_replies = 0
    wins = 0
    depths = set()
    while queue:
        board = queue.popleft()
        x_nodes += 1
        depths.add(9 - board.count('.'))
        if outcome(board) is not None:
            errors.append('policy covers a terminal board: %s' % board)
            continue
        if to_move(board) != 'X':
            errors.append('policy board is not X-to-move: %s' % board)
            continue
        if board not in policy:
            errors.append('no X action for reached board: %s' % board)
            continue
        action = tuple(policy[board])
        legal = dict(moves(board, 'X'))
        if action not in legal:
            errors.append('illegal X action %r at %s' % (action, board))
            continue
        after = legal[action]
        res = outcome(after)
        if res is not None:
            if res != 'X':
                errors.append('X move at %s ends in %r, not a win' % (board, res))
            else:
                wins += 1
            continue
        for _, reply in moves(after, 'O'):
            o_replies += 1
            res = outcome(reply)
            if res is not None:
                if res != 'X':
                    errors.append('O reply %s from %s ends in %r' % (reply, after, res))
                else:
                    wins += 1
                continue
            if reply not in seen:
                seen.add(reply)
                queue.append(reply)
    stats = {'x_decision_nodes': x_nodes, 'policy_entries': len(policy),
             'o_replies_examined': o_replies, 'terminal_X_wins': wins,
             'x_node_plies': sorted(depths),
             'unused_policy_entries': len(set(policy) - seen)}
    return errors, stats


def main():
    here = os.path.dirname(os.path.abspath(__file__))
    path = sys.argv[1] if len(sys.argv) > 1 else os.path.join(here, 'certificate.json')
    cert = json.load(open(path))
    errors, stats = check(cert)
    print(json.dumps(stats, indent=1))
    if errors:
        print('REJECTED: %d problem(s)' % len(errors))
        for e in errors[:20]:
            print(' -', e)
        sys.exit(1)
    print('VERIFIED: X forces a win from %s against every legal O reply.' % cert['root'])
    sys.exit(0)


if __name__ == '__main__':
    main()
```

