import json, hashlib
from collections import Counter
W=((0,1,2),(3,4,5),(6,7,8),(0,3,6),(1,4,7),(2,5,8),(0,4,8),(2,4,6))
def end(s):
    wins={s[a] for a,b,c in W if s[a]!='.' and s[a]==s[b]==s[c]}
    if len(wins)==2:return 0
    if wins:return 1 if 'X' in wins else -1
    if '.' not in s:return 0
    return None
def moves(s,p):
    for i,v in enumerate(s):
        if v!='.':continue
        b=s[:i]+p+s[i+1:];r,c=divmod(i,3)
        for ids in [(3*r,3*r+1,3*r+2),(c,c+3,c+6)]:
            x,y,z=(b[j] for j in ids)
            for triple in [(y,z,x),(z,x,y)]:
                q=list(b)
                for j,v in zip(ids,triple):q[j]=v
                yield ''.join(q)
levels=[{'.'*9}];edges={}
for depth in range(9):
    nxt=set();p='X' if depth%2==0 else 'O'
    for s in levels[-1]:
        if end(s) is not None:continue
        edges[s]=set(moves(s,p));nxt.update(edges[s])
    levels.append(nxt)
values={}
for depth in range(9,-1,-1):
    for s in levels[depth]:
        terminal=end(s)
        values[s]=terminal if terminal is not None else (max if depth%2==0 else min)(values[t] for t in edges[s])
canon='\n'.join(s+'\t'+('X' if (9-s.count('.'))%2==0 else 'O')+'\t'+str(values[s]) for s in sorted(values))
result={'method':'forward reachable layers, stop at terminals; bottom-up values without pruning','states':len(values),'layers':[len(x) for x in levels],'empty':values['.'*9],'openings':{s:values[s] for s in sorted(levels[1])},'sha256':hashlib.sha256(canon.encode()).hexdigest()}
print(json.dumps(result,indent=2))
